"use client";
import type { ButtonHTMLAttributes } from "react";
import { DecodeCells, useDecode } from "./ascii-decode";
import "./ascii-decode.css";
import "./scramble-button.css";

export function ScrambleButton({
  children,
  className = "",
  type = "button",
  ...props
}: Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children"> & {
  children: string;
}) {
  const [cells, run] = useDecode(children, 560);
  return (
    <button
      {...props}
      type={type}
      className={`forme-scramble ${className}`}
      onPointerEnter={(e) => {
        run();
        props.onPointerEnter?.(e);
      }}
      onFocus={(e) => {
        run();
        props.onFocus?.(e);
      }}
    >
      <span className="forme-decode">
        <span className="forme-decode-final">{children}</span>
        <DecodeCells cells={cells} />
      </span>
    </button>
  );
}

.forme-scramble {
  box-sizing: border-box;
  align-self: center;
  --forme-decode-noise: #a1a1aa;
  display: inline-flex;
  align-items: center;
  height: 48px;
  padding: 0 26px;
  border: 1px solid #ffffff24;
  border-radius: 999px;
  background: transparent;
  color: #ededf0;
  font: inherit;
  font-size: 15px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  cursor: pointer;
  transition:
    background 0.25s,
    border-color 0.25s,
    transform 0.2s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.forme-scramble:hover,
.forme-scramble:focus-visible {
  background: #ffffff0d;
  border-color: #ffffff40;
}
.forme-scramble:active {
  transform: scale(0.98);
}
.forme-scramble:focus-visible {
  outline: 2px solid #ededf0;
  outline-offset: 3px;
}
.forme-scramble:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
@media (prefers-reduced-motion: reduce) {
  .forme-scramble {
    transition: none;
  }
  .forme-scramble:active {
    transform: none;
  }
}

"use client";
import { createElement, useCallback, useEffect, useRef, useState } from "react";
import "./ascii-decode.css";

// Glyphs from the same face as the text, so the noise reads as type, not symbols.
const glyphs = "abcdeghknopqrsuvxyz0123456789";
type Cell = { ch: string; done: boolean };
const settled = (text: string): Cell[] => Array.from(text, (ch) => ({ ch, done: true }));

/** Returns the current cells and a function that decodes the text from noise.
 * Each character resolves on its own staggered schedule, roughly left to right. */
export function useDecode(text: string, duration = 900) {
  const [cells, setCells] = useState<Cell[]>(() => settled(text));
  const frame = useRef(0);
  const run = useCallback(() => {
    cancelAnimationFrame(frame.current);
    if (matchMedia("(prefers-reduced-motion:reduce)").matches) return setCells(settled(text));
    const chars = Array.from(text);
    const at = chars.map((_, i) => (i / Math.max(1, chars.length)) * 0.7 + Math.random() * 0.3);
    const start = performance.now();
    let step = -1;
    const tick = (now: number) => {
      const progress = Math.min(1, (now - start) / duration);
      // Fresh noise every 50 ms reads as decoding rather than flicker.
      if (Math.floor((now - start) / 50) !== step || progress === 1) {
        step = Math.floor((now - start) / 50);
        setCells(
          chars.map((ch, i) =>
            progress >= at[i] || ch === " "
              ? { ch, done: true }
              : { ch: glyphs[Math.floor(Math.random() * glyphs.length)], done: false },
          ),
        );
      }
      if (progress < 1) frame.current = requestAnimationFrame(tick);
    };
    frame.current = requestAnimationFrame(tick);
  }, [text, duration]);
  useEffect(() => {
    setCells(settled(text));
    return () => cancelAnimationFrame(frame.current);
  }, [text]);
  return [cells, run] as const;
}

export function DecodeCells({ cells }: { cells: Cell[] }) {
  return (
    <span className="forme-decode-live" aria-hidden="true">
      {cells.map((cell, i) => (
        <span key={i} data-scrambling={cell.done ? undefined : ""}>
          {cell.ch}
        </span>
      ))}
    </span>
  );
}

export function AsciiDecode({
  text,
  as = "span",
  className = "",
  duration = 1100,
  replayOnHover = true,
}: {
  text: string;
  as?: "span" | "h1" | "h2" | "h3" | "p";
  className?: string;
  duration?: number;
  replayOnHover?: boolean;
}) {
  const ref = useRef<HTMLElement>(null);
  const [cells, run] = useDecode(text, duration);
  useEffect(() => {
    const observer = new IntersectionObserver(([entry]) => {
      if (!entry.isIntersecting) return;
      run();
      observer.disconnect();
    });
    observer.observe(ref.current!);
    return () => observer.disconnect();
  }, [run]);
  return createElement(
    as,
    {
      ref,
      className: `forme-decode ${className}`,
      onPointerEnter: replayOnHover ? run : undefined,
    },
    <span className="forme-decode-final">{text}</span>,
    <DecodeCells cells={cells} />,
  );
}

.forme-decode {
  --forme-decode-noise: #8ab4ff;
  position: relative;
}
/* The real text holds layout and stays readable to assistive technology. */
.forme-decode-final {
  color: transparent;
}
.forme-decode-live {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.forme-decode-live > span {
  transition: color 0.35s, opacity 0.35s, text-shadow 0.35s;
}
.forme-decode-live > span[data-scrambling] {
  color: var(--forme-decode-noise);
  opacity: 0.45;
  text-shadow: 0 0 18px var(--forme-decode-noise);
  transition: none;
}
/* Inline decodes (buttons, labels) never wrap or spill while glyphs churn. */
span.forme-decode {
  display: inline-block;
  white-space: nowrap;
}
span.forme-decode .forme-decode-live {
  overflow: hidden;
  text-align: left;
}
@media (prefers-reduced-motion: reduce) {
  .forme-decode-live > span {
    transition: none;
  }
}
